package com.bank.pipeline.stage;

import com.bank.pipeline.model.Event;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Stage 2 — validate; route poison records to the dead-letter queue.
public class CleanStage {
    private static final Logger log = Logger.getLogger(CleanStage.class.getName());
    private final List<Event> deadLetterQueue = new ArrayList<>();

    public List<Event> clean(List<Event> events) {
        log.info("CLEAN: validating records, routing bad ones to DLQ");
        List<Event> good = new ArrayList<>();
        for (Event e : events) {
            if (e.getAmount() == null || e.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
                deadLetterQueue.add(e);
                log.warning(() -> "DLQ: quarantined poison record " + e.getTxnId());
            } else {
                good.add(e);
            }
        }
        return good;
    }
    public List<Event> getDeadLetterQueue() { return deadLetterQueue; }
}
