package com.bank.pipeline.stage;

import com.bank.pipeline.model.*;
import java.util.*;
import java.util.logging.Logger;

// Stage 3 — enrich each clean event with customer data.
public class JoinStage {
    private static final Logger log = Logger.getLogger(JoinStage.class.getName());
    private final Map<String, Customer> customers;

    public JoinStage(Map<String, Customer> customers) { this.customers = customers; }

    public List<EnrichedEvent> join(List<Event> events) {
        log.info("JOIN: enriching events with customer table");
        List<EnrichedEvent> out = new ArrayList<>();
        for (Event e : events) {
            Customer c = customers.get(e.getCustomerId());
            String name = c != null ? c.getName() : "UNKNOWN";
            out.add(new EnrichedEvent(e.getTxnId(), e.getCustomerId(), name, e.getAmount()));
        }
        return out;
    }
}
