package com.bank.pipeline.stage;

import com.bank.pipeline.model.EnrichedEvent;
import java.util.*;
import java.util.logging.Logger;

// Stage 4 — idempotent upsert into the warehouse (keyed by txn id).
public class LoadStage {
    private static final Logger log = Logger.getLogger(LoadStage.class.getName());
    private final Map<String, EnrichedEvent> warehouse = new LinkedHashMap<>();

    public void load(List<EnrichedEvent> events) {
        log.info("LOAD: upserting into warehouse");
        for (EnrichedEvent e : events) warehouse.put(e.getTxnId(), e);
    }
    public Map<String, EnrichedEvent> getWarehouse() { return warehouse; }
}
