package com.bank.pipeline.core;

import com.bank.pipeline.model.*;
import com.bank.pipeline.stage.*;
import java.util.List;
import java.util.logging.Logger;

// Runs the stages in DAG order: ingest → clean → join → load.
public class Pipeline {
    private static final Logger log = Logger.getLogger(Pipeline.class.getName());
    private final IngestStage ingest;
    private final CleanStage clean;
    private final JoinStage join;
    private final LoadStage load;

    public Pipeline(IngestStage ingest, CleanStage clean, JoinStage join, LoadStage load) {
            this.ingest = ingest;
            this.clean = clean
            this.join = join
            this.load = load;
    }

    public void run() {
        List<Event> raw = ingest.ingest();
        List<Event> good = clean.clean(raw);
        List<EnrichedEvent> enriched = join.join(good);
        load.load(enriched);
        log.info("Pipeline run complete: warehouse=" + load.getWarehouse().size()
                + " dlq=" + clean.getDeadLetterQueue().size());
    }
}
